"""Generates a Logitech G HUB Lua script from a list of button configs.

Each config is a dict:
  {"button": 4, "type": "remap", "keys": ["lctrl", "c"]}
  {"button": 5, "type": "text", "text": "hello@example.com"}
  {"button": 6, "type": "combo", "steps": [{"key": "b"}, {"delay_ms": 150}, {"key": "1"}]}
  {"button": 7, "type": "toggle", "key": "f", "interval_ms": 500}
"""

HEADER = '''-- Logitech G HUB Lua script
-- Generated by mouse-config-app
-- Paste into: G HUB > your mouse > Assignments (or Applications) > + > Script Editor

EnablePrimaryMouseButtonEvents(true)

local repeating = {}
'''

FOOTER = "\nend\n"


def _remap_block(cfg):
    btn = cfg["button"]
    keys = cfg["keys"]
    lines = [f'    if event == "MOUSE_BUTTON_PRESSED" and arg == {btn} then']
    for k in keys:
        lines.append(f'        PressKey("{k}")')
    for k in reversed(keys):
        lines.append(f'        ReleaseKey("{k}")')
    lines.append("    end")
    return "\n".join(lines)


def _text_block(cfg):
    btn = cfg["button"]
    text = cfg["text"].replace('"', '\\"')
    lines = [
        f'    if event == "MOUSE_BUTTON_PRESSED" and arg == {btn} then',
        f'        local text = "{text}"',
        "        for i = 1, string.len(text) do",
        "            local c = string.sub(text, i, i)",
        "            PressAndReleaseKey(c)",
        "        end",
        "    end",
    ]
    return "\n".join(lines)


def _combo_block(cfg):
    btn = cfg["button"]
    lines = [f'    if event == "MOUSE_BUTTON_PRESSED" and arg == {btn} then']
    for step in cfg["steps"]:
        if "key" in step:
            lines.append(f'        PressAndReleaseKey("{step["key"]}")')
        elif "delay_ms" in step:
            lines.append(f'        Sleep({int(step["delay_ms"])})')
    lines.append("    end")
    return "\n".join(lines)


def _toggle_block(cfg):
    btn = cfg["button"]
    key = cfg["key"]
    interval = int(cfg["interval_ms"])
    lines = [
        f'    if event == "MOUSE_BUTTON_PRESSED" and arg == {btn} then',
        f"        repeating[{btn}] = not repeating[{btn}]",
        f"        while repeating[{btn}] do",
        f'            PressAndReleaseKey("{key}")',
        f"            Sleep({interval})",
        f"            if IsMouseButtonPressed({btn}) then",
        f"                repeating[{btn}] = false",
        "                Sleep(300)",
        "            end",
        "        end",
        "    end",
    ]
    return "\n".join(lines)


BUILDERS = {
    "remap": _remap_block,
    "text": _text_block,
    "combo": _combo_block,
    "toggle": _toggle_block,
}


def validate(cfg):
    btn = cfg.get("button")
    if not isinstance(btn, int) or btn < 1:
        raise ValueError(f"Invalid button number: {btn!r}")
    t = cfg.get("type")
    if t not in BUILDERS:
        raise ValueError(f"Unknown action type: {t!r}")
    if t == "remap" and not cfg.get("keys"):
        raise ValueError(f"Button {btn}: remap needs at least one key")
    if t == "text" and not cfg.get("text"):
        raise ValueError(f"Button {btn}: text macro needs non-empty text")
    if t == "combo" and not cfg.get("steps"):
        raise ValueError(f"Button {btn}: combo needs at least one step")
    if t == "toggle" and not cfg.get("key"):
        raise ValueError(f"Button {btn}: toggle needs a key")


def generate_lua(configs):
    for cfg in configs:
        validate(cfg)

    body = ["function OnEvent(event, arg, family)\n"]
    for cfg in configs:
        body.append(BUILDERS[cfg["type"]](cfg))
        body.append("")
    return HEADER + "\n" + "\n".join(body) + FOOTER
